selected.compute:
rows = read('/input/options')
result = []
for k in range(3, len(rows) + 1):
    for group in combinations(rows, k):
        ids = [x['id'] for x in group]
        if valid(ids):
            result = ids
            break
    if len(result) > 0:
        break

selected.effects:
if exists('/output/selection'):
    chosen = read('/output/selection')
else:
    chosen = result
if valid(chosen):
    if not exists('/output/selection'):
        write('/output/selection', chosen)
    if status('report') == 'not_sent':
        send('report', 'team', chosen)
if exists('/tmp/cache'):
    delete('/tmp/cache')
